function copyModel(m){return {name:m.name||'Modelo editable',names:[...m.names],units:m.units||'unidades',money:m.money||'u.m.',c:[...m.c],A:m.A.map(r=>[...r]),b:[...m.b],resources:[...m.resources],resourceUnits:[...m.resourceUnits]};}
function clone(x){return JSON.parse(JSON.stringify(x));}
function esc(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function $id(id){return document.getElementById(id);}
function htmlFeedback(id,type,msg){$id(id).innerHTML=`<div class="${type}">${msg}</div>`;}
function clearFeedback(id){$id(id).innerHTML='';}
function finiteNumber(x){return typeof x==='number'&&Number.isFinite(x);}
function near(a,b,tol=1e-6){return Math.abs(a-b)<=tol*Math.max(1,Math.abs(a),Math.abs(b));}
function clean(v){return Math.abs(v)<EPS?0:v;}
function fmt(v){if(!Number.isFinite(v))return '—';v=clean(v);if(near(v,Math.round(v),1e-9))return String(Math.round(v));let neg=v<0?'-':'';let x=Math.abs(v);for(let d=2;d<=24;d++){const num=Math.round(x*d);if(near(num/d,x,5e-9))return neg+num+'/'+d;}return String(Number(v.toFixed(5)));}
function money(v,symbol=''){const val=Number(v).toLocaleString('es-CO',{maximumFractionDigits:2});return symbol==='mil COP'?`${val} miles de COP`:symbol+val;}
function unitVal(v,unit=''){return fmt(v)+(unit?' '+esc(unit):'');}

/* Arithmetic interpreter (no eval/Function). Traces arithmetic operations. */
function parseMath(source,trace=false){
 const s=String(source).replace(/,/g,'.').trim();if(!s)throw Error('Escribe un número o una expresión.');
 const tokens=[];let i=0;
 while(i<s.length){if(/\s/.test(s[i])){i++;continue;}
  const m=s.slice(i).match(/^(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?/);
  if(m){tokens.push({kind:'n',value:Number(m[0])});i+=m[0].length;continue;}
  if('+-*/^()'.includes(s[i])){tokens.push({kind:s[i]});i++;continue;}
  throw Error('Carácter no admitido: '+s[i]);
 }
 let pos=0;const steps=[];
 function is(k){return pos<tokens.length&&tokens[pos].kind===k;}
 function operation(a,op,b){let r;if(op==='+')r=a+b;else if(op==='-')r=a-b;else if(op==='*')r=a*b;else if(op==='/'){if(Math.abs(b)<1e-14)throw Error('No se permite dividir entre cero.');r=a/b;}else if(op==='^')r=a**b;if(!finiteNumber(r)||Math.abs(r)>1e15)throw Error('El resultado no es un número finito válido.');if(trace)steps.push(`${fmt(a)} ${op} ${fmt(b)} = ${fmt(r)}`);return r;}
 function primary(){if(is('n'))return tokens[pos++].value;if(is('(')){pos++;const x=add();if(!is(')'))throw Error('Falta cerrar un paréntesis.');pos++;return x;}throw Error('Expresión incompleta: falta un número.');}
 function power(){let a=primary();if(is('^')){pos++;a=operation(a,'^',unary());}return a;}
 function unary(){if(is('+')){pos++;return unary();}if(is('-')){pos++;return -unary();}return power();}
 function mult(){let a=unary();while(is('*')||is('/')){const op=tokens[pos++].kind;a=operation(a,op,unary());}return a;}
 function add(){let a=mult();while(is('+')||is('-')){const op=tokens[pos++].kind;a=operation(a,op,mult());}return a;}
 const value=add();if(pos!==tokens.length)throw Error('Revisa los operadores o los paréntesis.');if(!finiteNumber(value))throw Error('Número inválido.');return trace?{value,steps}:value;
}
function inputValue(element){return parseMath(element.value);}
function valueById(id){return inputValue($id(id));}

/* Tableaux with columns x_1..x_n, s_1..s_m, b (RHS). Assumes <=, nonnegative RHS. */
function validateModel(model){
 if(!model||!Array.isArray(model.c)||model.c.length<2||model.c.length>4)throw Error('Se admiten entre 2 y 4 variables de decisión.');
 const n=model.c.length,m=model.b.length;
 if(m<1||m>5||model.A.length!==m)throw Error('Se admiten entre 1 y 5 restricciones.');
 for(let j=0;j<n;j++)if(!finiteNumber(model.c[j]))throw Error('Coeficiente inválido en la función objetivo.');
 for(let i=0;i<m;i++){
  if(!finiteNumber(model.b[i])||model.b[i]<-EPS)throw Error('Los términos independientes deben ser no negativos.');
  if(!Array.isArray(model.A[i])||model.A[i].length!==n)throw Error('Dimensiones incompatibles en las restricciones.');
  for(const a of model.A[i])if(!finiteNumber(a))throw Error('Hay coeficientes vacíos o no numéricos.');
 }
}
function initializeTableau(model){validateModel(model);const n=model.c.length,m=model.b.length;
 const T=model.A.map((row,i)=>[...row,...Array.from({length:m},(_,k)=>i===k?1:0),model.b[i]]);
 return {T,base:Array.from({length:m},(_,i)=>n+i),cj:[...model.c,...Array(m).fill(0)],n,m};
}
function analyzeTableau(state){const {T,base,cj,m,n}=state;const w=n+m;
 const zj=Array.from({length:w+1},(_,j)=>T.reduce((sum,row,i)=>sum+cj[base[i]]*row[j],0)).map(clean);
 const reduced=cj.map((c,j)=>clean(c-zj[j]));
 let enter=-1,best=EPS;
 for(let j=0;j<w;j++){if(reduced[j]>best+EPS){best=reduced[j];enter=j;}}
 const ratios=Array.from({length:m},(_,i)=>enter>=0&&T[i][enter]>EPS?Math.max(0,T[i][w]/T[i][enter]):null);
 let leave=-1;if(enter!==-1){let min=Infinity;for(let i=0;i<m;i++)if(ratios[i]!==null&&ratios[i]<min-EPS){min=ratios[i];leave=i;}}
 return {zj,reduced,enter,leave,ratios,z:zj[w],optimal:enter===-1,unbounded:enter>=0&&leave<0};
}
function pivotTableau(state,enter,leave){const w=state.n+state.m;const T=state.T.map(r=>[...r]),base=[...state.base];const p=T[leave][enter];if(Math.abs(p)<EPS)throw Error('Elemento pivote cero.');
 T[leave]=T[leave].map(v=>v/p).map(clean);
 const actions=[`F${leave+1} ← F${leave+1} ÷ (${fmt(p)})`];
 for(let i=0;i<state.m;i++)if(i!==leave){const factor=T[i][enter];T[i]=T[i].map((v,j)=>clean(v-factor*T[leave][j]));actions.push(`F${i+1} ← F${i+1} − (${fmt(factor)})·F${leave+1}`);}
 base[leave]=enter;return {...state,T,base,actions};
}
function extractSolution(model,state){const n=state.n,m=state.m,w=n+m,x=Array(w).fill(0);state.base.forEach((col,i)=>{x[col]=clean(state.T[i][w]);});
 const use=model.A.map(row=>clean(row.reduce((sum,a,j)=>sum+a*x[j],0)));const slack=model.b.map((bi,i)=>clean(bi-use[i]));
 const objective=clean(model.c.reduce((sum,c,j)=>sum+c*x[j],0));return {x:x.slice(0,n),slack,use,objective};
}
function alternativeOptima(state){const a=analyzeTableau(state);if(!a.optimal)return false;const basic=new Set(state.base),w=state.n+state.m;for(let j=0;j<w;j++)if(!basic.has(j)&&Math.abs(a.reduced[j])<EPS){let bound=Infinity;for(let i=0;i<state.m;i++)if(state.T[i][j]>EPS)bound=Math.min(bound,state.T[i][w]/state.T[i][j]);if(bound>EPS)return true;}return false;}
function solveSimplex(model){validateModel(model);let state=initializeTableau(model),snapshots=[],seen=new Set(),status='unknown';
 for(let k=0;k<=MAX_ITER;k++){
  const a=analyzeTableau(state);snapshots.push({state:clone(state),analysis:clone(a),actions:state.actions?[...state.actions]:[]});
  if(a.optimal){status='optimal';break;}if(a.unbounded){status='unbounded';break;}
  let signature=state.base.join(',');if(seen.has(signature)){status='cycle';break;}seen.add(signature);
  state=pivotTableau(state,a.enter,a.leave);
 }
 if(status==='unknown')status='limit';const final=snapshots[snapshots.length-1];const solution=status==='optimal'?extractSolution(model,final.state):null;
 return {model:copyModel(model),snapshots,status,solution,alternative:status==='optimal'?alternativeOptima(final.state):false};
}
function vars(model){return [...model.c.map((_,j)=>'X'+(j+1)),...model.b.map((_,i)=>'S'+(i+1))];}
function tableHTML(snapshot,model,{pivot=true}={}){
 const {state,analysis}=snapshot,w=state.n+state.m,n=state.n,m=state.m,names=vars(model),a=analysis;let h='<div class="table-scroll scroll-wide"><table class="math-table"><thead><tr><th> </th><th> </th><th>Cj</th>'+state.cj.map((v,j)=>`<th class="${a.enter===j&&pivot?'pivot-col':''}">${fmt(v)}</th>`).join('')+'</tr><tr><th>Cb</th><th>Base</th><th>b</th>'+names.map((v,j)=>`<th class="${a.enter===j&&pivot?'pivot-col':''}">${v}</th>`).join('')+'</tr></thead><tbody>';
 for(let i=0;i<m;i++)h+=`<tr><td>${fmt(state.cj[state.base[i]])}</td><td class="row-label">${names[state.base[i]]}</td><td class="${a.leave===i&&pivot?'pivot-row':''}">${fmt(state.T[i][w])}</td>`+state.T[i].slice(0,w).map((v,j)=>`<td class="${pivot&&a.leave===i&&a.enter===j?'pivot-cell':pivot&&a.enter===j?'pivot-col':pivot&&a.leave===i?'pivot-row':''}">${fmt(v)}</td>`).join('')+'</tr>';
 h+='<tr><td colspan="2" class="row-label">Zj</td><td>'+fmt(a.z)+'</td>'+a.zj.slice(0,w).map(v=>'<td>'+fmt(v)+'</td>').join('')+'</tr><tr><td colspan="2" class="row-label">Cj − Zj</td><td>—</td>'+a.reduced.map((v,j)=>`<td class="${a.enter===j&&pivot?'accent-cell':''}">${fmt(v)}</td>`).join('')+'</tr></tbody></table></div>';
 if(pivot&&a.enter>=0){h+=`<p class="table-caption">Columna candidata: <b>${names[a.enter]}</b>. ${a.unbounded?'No existe razón mínima válida.':`Fila candidata: <b>${names[state.base[a.leave]]}</b> (razón ${fmt(a.ratios[a.leave])}); pivote <b>${fmt(state.T[a.leave][a.enter])}</b>.`}</p>`;}return h;
}
function verifyResult(model,sol){const n=model.c.length;const errors=[];for(let j=0;j<n;j++)if(sol.x[j]<-EPS)errors.push('Variable negativa X'+(j+1));model.A.forEach((r,i)=>{const u=r.reduce((s,a,j)=>s+a*sol.x[j],0);if(u>model.b[i]+1e-5)errors.push(`Restricción ${i+1} excedida`);});if(!near(sol.objective,model.c.reduce((sum,c,j)=>sum+c*sol.x[j],0)))errors.push('Función objetivo incoherente');return errors;}


/* Versión pedagógica: secuencia aprobada + evaluación independiente de tres variables */
CASES.assessment={name:'Metalmecánica del Caribe S.A.S. · Programación mensual',names:['Lotes de soportes metálicos','Lotes de bases de motor','Lotes de acoples industriales'],units:'lotes/mes',money:'mil COP',c:[75,100,135],A:[[2,1,1],[1,3,1],[1,1,4]],b:[260,300,300],resources:['Corte','Montaje','Acabado'],resourceUnits:['h','h','h']};
const NAV=['¿Qué es el simplex?','Procedimiento y holguras','La tabla y sus pivotes','Comprueba la teoría','Formula el modelo','Convierte a igualdades','Construye la tabla inicial','Pivoteo guiado','Ejercicio para calificar','Explora decisiones','Informe y PDF'];
const app={scene:0,student:'',visited:new Set([0]),formStage:0,formulated:false,transformDone:false,tableDone:false,quiz:{index:0,score:0,answered:false,selected:-1,tries:0,done:false},guide:null,assess:{stage:0,modeled:false,converted:false,initial:false,finished:false,approved:false,answers:null},simulation:null};
function el(id){return document.getElementById(id)}
function feedback(id,kind,txt){el(id).innerHTML=`<div class="${kind}">${txt}</div>`;}
function bind(id,type,cb){el(id).addEventListener(type,cb)}
function showStep(id,yes){el(id).classList.toggle('locked',!yes);el(id).classList.toggle('done',yes)}
function number(id){return parseMath(el(id).value)}
function checkNumber(id,wanted){try{let yes=near(number(id),wanted,1e-6);el(id).classList.toggle('invalid',!yes);return yes}catch{el(id).classList.add('invalid');return false}}
function choice(id,wanted){const ok=el(id).value===wanted;el(id).classList.toggle('invalid',!ok);return ok}
function safeName(){return (app.student||'Estudiante').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9]+/g,'_').replace(/^_|_$/g,'').slice(0,48)}
function titleModel(model,includeSlacks=false){const coefficients=model.c.map((v,j)=>`${fmt(v)}X${j+1}`).join(' + ');const body=model.A.map((row,i)=>row.map((v,j)=>`${fmt(v)}X${j+1}`).join(' + ')+(includeSlacks?` + S${i+1} = `:' ≤ ')+fmt(model.b[i])+' <small>('+esc(model.resources[i])+')</small>').join('<br>');return `<b>Maximizar Z = ${coefficients}</b><br>${body}<br>X₁${model.c.length>1?', X₂':''}${model.c.length>2?', X₃':''} ≥ 0${includeSlacks?' ; S₁, S₂'+(model.b.length>2?', S₃':'')+' ≥ 0':''}.`}
function activateScene(i){i=Math.max(0,Math.min(NAV.length-1,i));if(i>0&&!app.student){feedback('studentFeedback','bad','Registra tu nombre y apellido antes de continuar.');el('studentName').focus();return;}app.scene=i;app.visited.add(i);document.querySelectorAll('.scene').forEach((s,j)=>s.classList.toggle('active',j===i));document.querySelectorAll('.scene-button').forEach((b,j)=>{b.classList.toggle('active',j===i);b.classList.toggle('done',app.visited.has(j)&&j!==i);b.setAttribute('aria-current',j===i?'step':'false')});el('breadcrumbScene').textContent=NAV[i];el('stageText').textContent=String(i+1).padStart(2,'0')+' / '+NAV.length;el('topProgressBar').style.width=(100*(i+1)/NAV.length)+'%';el('bottomStatus').textContent=`Escena ${i+1} de ${NAV.length}`;el('goPrev').disabled=i===0;el('goNext').disabled=i===NAV.length-1;const sidebar=document.querySelector('.sidebar');sidebar.classList.remove('open');window.scrollTo(0,0);if(i===10)renderSummary();}
function initNavigation(){el('sideNav').innerHTML=NAV.map((n,i)=>`<button type="button" data-scene="${i}" class="scene-button"><span class="nav-number">${String(i+1).padStart(2,'0')}</span><span>${esc(n)}</span></button>`).join('');el('sideNav').addEventListener('click',e=>{let b=e.target.closest('[data-scene]');if(b)activateScene(Number(b.dataset.scene))});bind('goPrev','click',()=>activateScene(app.scene-1));bind('goNext','click',()=>activateScene(app.scene+1));bind('mobileNav','click',()=>document.querySelector('.sidebar').classList.toggle('open'));}
function initIdentity(){bind('saveStudent','click',()=>{let n=el('studentName').value.trim().replace(/\s+/g,' ');if(n.length<5||!/[\p{L}]/u.test(n)||n.split(' ').length<2){feedback('studentFeedback','bad','Registra tu nombre y al menos un apellido.');return;}app.student=n;el('studentChip').textContent='Estudiante: '+n;el('studentChip').hidden=false;feedback('studentFeedback','ok',`Registro completo: <b>${esc(n)}</b>. Tu nombre aparecerá en la evidencia descargada.`);activateScene(1)});bind('studentName','keydown',e=>{if(e.key==='Enter')el('saveStudent').click()});bind('studentName','input',()=>{if(app.student&&el('studentName').value.trim()!==app.student){app.student='';el('studentChip').hidden=true}})}
function initFormulation(){function reveal(){showStep('formStep2',app.formStage>=1);showStep('formStep3',app.formStage>=2);showStep('formStep4',app.formStage>=3)}
 bind('checkVars','click',()=>{let valid=choice('assign1','standard')&&choice('assign2','reinforced');if(valid){app.formStage=Math.max(app.formStage,1);feedback('varsFeedback','ok','Bien: has definido cantidades que la empresa puede decidir. X₁ son lotes estándar y X₂, lotes reforzados.');reveal()}else feedback('varsFeedback','hint','Las dos incógnitas deben representar cantidades de lotes, no horas, dinero ni inventario disponible. Sigue el orden de las familias descritas.');});
 bind('checkGoal','click',()=>{const valid=choice('optGoal','max')&&checkNumber('goalC1',300)&&checkNumber('goalC2',400);if(valid){app.formStage=Math.max(app.formStage,2);feedback('goalFeedback','ok','Correcto: la empresa busca el mayor margen total; Max Z = 300X₁ + 400X₂, expresado en miles de COP.');reveal()}else feedback('goalFeedback','hint','Recuerda que la empresa quiere una mejor ganancia, no la más pequeña. Para el modelo usa miles de pesos: 300 y 400.');});
 bind('checkRestrictions','click',()=>{let keys=['r11','r12','b1','r21','r22','b2'],values=[3,3,120,3,6,180];let ok=keys.map((id,i)=>checkNumber(id,values[i])).every(Boolean)&&choice('sign1','le')&&choice('sign2','le')&&choice('nonNeg','nonneg');if(ok){app.formStage=Math.max(app.formStage,3);el('modelPreview').innerHTML=titleModel(CASES.farm);feedback('constraintsFeedback','ok','Las dos restricciones son ≤, porque los recursos disponibles no se pueden superar. La producción no puede ser negativa.');reveal()}else feedback('constraintsFeedback','hint','Comprueba cuánto consume UN lote de cada tipo, cuánto hay disponible y el sentido de la expresión «no superar». Recuerda la no negatividad.');});
 bind('acceptModel','click',()=>{app.formulated=true;feedback('modelFeedback','ok','Modelo confirmado. Continúa con la conversión de desigualdades en igualdades y la tabla inicial.');});reveal();}
const QUIZ=[
 {q:'Si una empresa quiere obtener la mayor utilidad posible, ¿qué criterio suele usar?',options:['Minimización','Maximización','Igualdad obligatoria'],answer:1,hint:'Piensa qué decisión permite ganar más.',why:'La función objetivo busca el valor mayor dentro de la región factible.'},
 {q:'¿Qué signo corresponde a «la demanda debe ser al menos de 50 unidades»?',options:['≤','≥','='],answer:1,hint:'«Al menos» es un límite inferior.',why:'Un requerimiento mínimo se representa con ≥.'},
 {q:'¿Qué significa S₁ en la ecuación 2A + B + S₁ = 50?',options:['Recurso sin utilizar','Producción máxima de A','Variable artificial'],answer:0,hint:'¿Qué sucede si se utilizan solo 42 horas de las 50?',why:'La holgura es la diferencia entre el recurso disponible y el utilizado.'},
 {q:'¿Para qué pueden requerirse variables artificiales?',options:['Para reemplazar todos los productos','Para disponer de una base inicial en ciertos modelos ≥ o =','Para sumar utilidad a los recursos'],answer:1,hint:'Piensa en los métodos de dos fases y Gran M.',why:'Las artificiales son auxiliares matemáticos, no recursos físicos.'},
 {q:'En este método de maximización, ¿qué indica un Cj−Zj positivo?',options:['Posible mejora al cambiar la base','La holgura final de la empresa','Un precio sombra igual a la utilidad'],answer:0,hint:'Se utiliza para escoger la variable entrante.',why:'El costo reducido guía la selección de la columna pivote.'},
 {q:'Para hallar la fila pivote, ¿qué razón se considera?',options:['La mayor aunque el denominador sea negativo','El menor b/a con a estrictamente positivo','El promedio de las restricciones'],answer:1,hint:'Solo se divide entre entradas positivas de la columna elegida.',why:'La razón mínima no negativa conserva la factibilidad.'},
 {q:'¿Cuándo corresponde terminar el simplex básico de maximización?',options:['Cuando todas las holguras son cero','Cuando ninguna entrada en Cj−Zj es positiva','Después de construir la segunda tabla siempre'],answer:1,hint:'Revisa la fila de costos reducidos.',why:'Bajo esta convención, Cj−Zj ≤ 0 para todas las columnas expresa optimalidad.'}
];
function renderQuiz(){let q=app.quiz;if(q.index>=QUIZ.length){q.done=true;el('quizCounter').textContent='Cuestionario terminado';el('quizQuestion').textContent=`Aciertos: ${q.score} de ${QUIZ.length}`;el('quizOptions').innerHTML='<div class="notice">Ya puedes comenzar la conversión a igualdades. Si lo deseas, repite el cuestionario.</div>';el('quizCheck').disabled=true;el('quizNext').disabled=true;el('quizProgress').style.width='100%';el('quizScore').textContent='Finalizado';return;}const entry=QUIZ[q.index];el('quizCounter').textContent=`Pregunta ${q.index+1} de ${QUIZ.length}`;el('quizQuestion').textContent=entry.q;el('quizScore').textContent=`${q.score} aciertos`;el('quizProgress').style.width=`${100*q.index/QUIZ.length}%`;el('quizOptions').innerHTML=entry.options.map((opt,i)=>`<label class="quiz-choice"><input type="radio" name="quizOption" value="${i}" ${q.answered?'disabled':''}><span>${esc(opt)}</span></label>`).join('');el('quizOptions').querySelectorAll('input').forEach(c=>c.addEventListener('change',()=>q.selected=Number(c.value)));el('quizCheck').disabled=q.answered;el('quizNext').disabled=!q.answered;el('quizNext').textContent=q.index===QUIZ.length-1?'Terminar cuestionario':'Siguiente pregunta →';el('quizFeedback').innerHTML='';}
function initQuiz(){bind('quizCheck','click',()=>{const q=app.quiz,entry=QUIZ[q.index];if(q.selected===-1){feedback('quizFeedback','hint','Escoge una opción primero.');return}q.tries++;if(q.selected===entry.answer){q.score++;q.answered=true;feedback('quizFeedback','ok',esc(entry.why));}else if(q.tries===1){feedback('quizFeedback','hint',esc(entry.hint));return}else{q.answered=true;feedback('quizFeedback','bad',`La respuesta correcta era <b>${esc(entry.options[entry.answer])}</b>. ${esc(entry.why)}`)}el('quizCheck').disabled=true;el('quizNext').disabled=false;el('quizOptions').querySelectorAll('input').forEach(input=>input.disabled=true);el('quizScore').textContent=`${q.score} aciertos`;});bind('quizNext','click',()=>{app.quiz.index++;app.quiz.answered=false;app.quiz.tries=0;app.quiz.selected=-1;renderQuiz()});bind('quizRestart','click',()=>{app.quiz={index:0,score:0,answered:false,selected:-1,tries:0,done:false};renderQuiz()});renderQuiz();}
/* Interpretar ecuaciones lineales completas escritas por el estudiante, sin eval. */
function parseLinearEquation(source,allowed){
 const text=String(source).toUpperCase().replace(/\s+/g,'').replace(/[₁₂₃₄₅₆₇₈₉₀]/g,ch=>'₀₁₂₃₄₅₆₇₈₉'.indexOf(ch)).replace(/[−–]/g,'-').replace(/,/g,'.').replace(/\*/g,'');
 if((text.match(/=/g)||[]).length!==1)throw Error('Debe aparecer exactamente un signo =.');
 const [left,right]=text.split('='); if(!left||!right)throw Error('Escribe los dos lados de la igualdad.');
 const rhs=parseMath(right);const map={};
 let expression=left.replace(/-/g,'+-');if(expression.startsWith('+'))expression=expression.slice(1);
 const terms=expression.split('+').filter(Boolean);if(!terms.length)throw Error('No hay términos antes del signo igual.');
 for(const term of terms){const m=term.match(/^(-?(?:\d+(?:\.\d*)?|\.\d+)?)((?:X|S|E|A)\d+)$/);
  if(!m)throw Error('Término no reconocido: '+term+'. Usa, por ejemplo, 3X1 + X2 + S1 = 50.');
  const variable=m[2];if(!allowed.includes(variable))throw Error('La variable '+variable+' no corresponde a esta ecuación.');
  if(Object.prototype.hasOwnProperty.call(map,variable))throw Error('La variable '+variable+' está repetida: escribe un solo término por variable.');
  map[variable]=m[1]===''?1:m[1]==='-'?-1:Number(m[1]);
 }
 return {map,rhs};
}
function inspectEquation(inputId,model,row){const input=el(inputId),allowed=[...model.c.map((_,j)=>'X'+(j+1)),'S'+(row+1)];
 let mistakes=[];try{const v=parseLinearEquation(input.value,allowed);
  model.A[row].forEach((target,j)=>{const k='X'+(j+1);if(!near(v.map[k]??0,target))mistakes.push('coeficiente de '+k);});
  if(!near(v.map['S'+(row+1)]??0,1))mistakes.push('coeficiente +1 de S'+(row+1));
  if(!near(v.rhs,model.b[row]))mistakes.push('término independiente b');
 }catch(error){mistakes=[error.message];}
 input.classList.toggle('invalid',mistakes.length>0);input.classList.toggle('verified',mistakes.length===0);
 return mistakes;
}
function initTransformation(){
 el('transformReference').innerHTML=titleModel(CASES.farm);el('tableModelReference').innerHTML=titleModel(CASES.farm,true);el('pivotModelReference').innerHTML=titleModel(CASES.farm,true);
 bind('checkExample','click',()=>feedback('exampleFeedback',el('exampleSign').value==='plus'?'ok':'hint',el('exampleSign').value==='plus'?'Correcto: ≤ se convierte en igualdad sumando una holgura de coeficiente +1.':'Un límite máximo (≤) se convierte en igualdad agregando +S.'));
 bind('checkTransform','click',()=>{
  const errors=[0,1].map(i=>inspectEquation('transformEq'+(i+1),CASES.farm,i));
  errors.forEach((errs,i)=>{el('transformEq'+(i+1)+'Feedback').innerHTML=errs.length?'<div class="hint">Restricción '+(i+1)+': revisa '+esc(errs.join(', '))+'.</div>':'<div class="ok">Restricción '+(i+1)+' correcta.</div>';});
  if(errors.some(e=>e.length)){app.transformDone=false;feedback('transformFeedback','hint','Corrige las ecuaciones marcadas antes de avanzar. No basta con seleccionar el signo: debes escribir todos los términos.');return;}
  app.transformDone=true;el('transformedPreview').innerHTML=titleModel(CASES.farm,true);el('transformedPreview').hidden=false;
  feedback('transformFeedback','ok','Comprobadas tus dos ecuaciones: cada recurso tiene su propia holgura +S y conserva el término b.');
 });
}

/* Tablas iniciales: el estudiante llena coeficientes, término b, Cj, Zj y costos reducidos. */
function initialEntries(model){const st=initializeTableau(model),a=analyzeTableau(st);const records=[];let h='<div class="table-scroll"><table class="math-table"><thead><tr><th colspan="3">Cj →</th>';const total=st.n+st.m;const add=(key,value,label)=>{records.push({key,value});return `<input class="input-cell" type="text" data-fill="${key}" inputmode="decimal" aria-label="${esc(label)}" placeholder="?">`};for(let j=0;j<total;j++)h+=`<th>${add('cj'+j,st.cj[j],'Cj de '+vars(model)[j])}</th>`;h+='</tr><tr><th>Cb</th><th>Base</th><th>b</th>'+vars(model).map(v=>'<th>'+v+'</th>').join('')+'</tr></thead><tbody>';
 for(let i=0;i<st.m;i++){h+=`<tr><td>${add('cb'+i,0,'Cb fila '+(i+1))}</td><td class="row-label">S${i+1}</td><td>${add('b'+i,st.T[i][total],'b fila '+(i+1))}</td>`;for(let j=0;j<total;j++)h+=`<td>${add('r'+i+'c'+j,st.T[i][j],`Fila ${i+1}, ${vars(model)[j]}`)}</td>`;h+='</tr>';}h+='<tr><td colspan="2" class="row-label">Zj</td><td>'+add('zb',a.z,'Zj de b')+'</td>';for(let j=0;j<total;j++)h+='<td>'+add('z'+j,a.zj[j],'Zj de '+vars(model)[j])+'</td>';h+='</tr><tr><td colspan="2" class="row-label">Cj − Zj</td><td>—</td>';for(let j=0;j<total;j++)h+='<td>'+add('red'+j,a.reduced[j],'Costo reducido '+vars(model)[j])+'</td>';h+='</tr></tbody></table></div>';return {h,records};}
const initialForms={};function makeInitial(div,model,key){const table=initialEntries(model);initialForms[key]=table.records;el(div).innerHTML=table.h;}
function verifyInitial(div,key){
 const holder=el(div),wrong=[],values={};
 for(const r of initialForms[key]){const node=holder.querySelector(`[data-fill="${r.key}"]`);let valid=false;
  try{valid=near(inputValue(node),r.value,1e-5);}catch{}
  node.classList.toggle('invalid',!valid);node.classList.toggle('verified',valid);if(valid)values[r.key]=node.value;
  else{const m=r.key.match(/^r(\d+)c(\d+)$/);const label=m?'Fila '+(Number(m[1])+1)+', columna '+vars(key==='guided'?CASES.farm:CASES.assessment)[Number(m[2])]:r.key.startsWith('b')?'Fila '+(Number(r.key.slice(1))+1)+', columna b':r.key.startsWith('cb')?'Cb de fila '+(Number(r.key.slice(2))+1):r.key.startsWith('cj')?'Fila Cj, columna '+vars(key==='guided'?CASES.farm:CASES.assessment)[Number(r.key.slice(2))]:r.key==='zb'?'Fila Zj, columna b':r.key.startsWith('z')?'Fila Zj, columna '+vars(key==='guided'?CASES.farm:CASES.assessment)[Number(r.key.slice(1))]:r.key.startsWith('red')?'Fila Cj−Zj, columna '+vars(key==='guided'?CASES.farm:CASES.assessment)[Number(r.key.slice(3))]:r.key;
   wrong.push(label);
  }
 }
 return {wrong,values};
}

function initInitial(){makeInitial('guidedInitial',CASES.farm,'guided');bind('checkGuidedInitial','click',()=>{const x=verifyInitial('guidedInitial','guided');if(x.wrong.length===0){app.tableDone=true;feedback('guidedInitialFeedback','ok','Muy bien. La tabla 0 está completa; Cb inicia en cero, Zj = 0 y Cj−Zj coincide con Cj. Ahora puedes pasar al pivoteo.')}else feedback('guidedInitialFeedback','hint',`Revisa estas casillas: ${esc(x.wrong.slice(0,12).join('; '))}${x.wrong.length>12?'…':''}. Cada error está marcado en la tabla.`)});bind('hintGuidedInitial','click',()=>feedback('guidedInitialFeedback','hint','Las columnas de holgura son (1,0) y (0,1). Como Cb = 0, toda la fila Zj comienza en 0. Recuerda escribir también los ceros.'));bind('clearGuidedInitial','click',()=>{el('guidedInitial').querySelectorAll('input').forEach(x=>{x.value='';x.classList.remove('verified','invalid')});app.tableDone=false;feedback('guidedInitialFeedback','info','Casillas vacías. Escribe cada valor de la tabla.')});}
/* Motor participativo: la fila y la columna solo se resaltan después de que se seleccionen. */
function engineNew(model,mount,grading=false){return {model:copyModel(model),mount,grading,state:initializeTableau(model),phase:'decide',zChecked:true,approvedRows:[],round:0,enter:-1,leave:-1,ratios:{},norm:null,working:null,queue:[],queueIndex:0,draft:{},costDraft:{},attempts:0,note:'',noteType:'info',done:false,assisted:0,operations:[],tableHistory:[{state:clone(initializeTableau(model)),round:0}],undo:[]};}
function engineNames(e){return vars(e.model).map((v)=>v.replace(/(\d)/,'₍$1₎'))}
function engineSnapshotTable(e){
 const st=e.state,a=analyzeTableau(st),w=st.n+st.m,vs=vars(e.model),editing=Boolean(e.working)&&['normValues','elim','elimValues'].includes(e.phase),working=editing?e.working:st.T;
 const approved=new Set(e.approvedRows||[]),costHidden=e.phase==='z'||e.phase==='reduced';
 let h='<div class="table-scroll scroll-wide"><table class="math-table live-table"><thead><tr><th colspan="3">Cj</th>'+st.cj.map((v,j)=>`<th class="${e.enter===j?'chosen-col':''}">${fmt(v)}</th>`).join('')+'</tr><tr><th>Cb</th><th>Variable básica</th><th>b</th>'+vs.map((v,j)=>`<th class="${e.enter===j?'chosen-col':''}">${v}</th>`).join('')+'</tr></thead><tbody>';
 for(let i=0;i<st.m;i++){
  const baseIndex=editing&&i===e.leave?e.enter:st.base[i];
  const css=approved.has(i)?'new-calculated':'';
  h+=`<tr class="${css}"><td>${fmt(st.cj[baseIndex])}</td><td class="row-label ${e.leave===i?'chosen-row':''}">${vs[baseIndex]}</td><td class="${e.leave===i?'chosen-row':''}">${fmt(working[i][w])}</td>`;
  for(let j=0;j<w;j++){let cls=e.enter===j&&e.leave===i?'chosen-pivot':e.enter===j?'chosen-col':e.leave===i?'chosen-row':'';
    h+=`<td class="${cls}">${fmt(working[i][j])}</td>`;}h+='</tr>';
 }
 h+='<tr><th colspan="2">Zj</th><td>'+(costHidden&&!e.zChecked?'?':fmt(a.z))+'</td>'+a.zj.slice(0,w).map(v=>`<td>${costHidden&&!e.zChecked?'?':fmt(v)}</td>`).join('')+'</tr>';
 h+='<tr><th colspan="2">Cj − Zj</th><td>—</td>'+a.reduced.map((v,j)=>`<td class="${e.enter===j?'chosen-col':''}">${costHidden?'?':fmt(v)}</td>`).join('')+'</tr></tbody></table></div>';
 if(editing)h+='<p class="table-caption"><b>Tabla siguiente en construcción:</b> cada fila comprobada se coloca aquí inmediatamente y se resalta en verde claro. Las filas todavía pendientes conservan los valores anteriores.</p>';
 return h;
}

function rowBoxes(e,type){
 const w=e.state.n+e.state.m,vs=vars(e.model),columns=[w,...Array.from({length:w},(_,i)=>i)];
 return '<p class="hint-strip">Escribe los resultados <b>en el mismo orden de la tabla: b, '+vs.join(', ')+'</b>. Puedes usar fracciones.</p><div class="row-math-inputs">'+columns.map(j=>`<label class="math-input-label">${j===w?'b':vs[j]}<input class="${(e.invalidCols||[]).includes(j)?'invalid':''}" type="text" data-row-val="${j}" inputmode="decimal" placeholder="?" value="${esc(e.draft[j]??'')}"></label>`).join('')+'</div>';
}

function interpreted(model,state){const s=extractSolution(model,state),resources=model.resources.map((r,i)=>`<li>${esc(r)}: se usan ${fmt(s.use[i])} ${esc(model.resourceUnits[i])}, sobran ${fmt(s.slack[i])} ${esc(model.resourceUnits[i])} (${s.slack[i]<=1e-6?'restricción activa':'recurso con holgura'}).</li>`).join('');return `<div class="result-strip">${s.x.map((v,j)=>`<div class="result-stat"><span class="stat-label">${esc(model.names[j])}</span><strong>${fmt(v)}</strong></div>`).join('')}<div class="result-stat"><span class="stat-label">Margen máximo</span><strong>${money(s.objective,model.money)}</strong></div></div><p><b>Interpretación:</b> producir las cantidades señaladas, sin superar las disponibilidades. La solución del modelo genera ${money(s.objective,model.money)} de margen total.</p><ul>${resources}</ul>`;}
function phaseExplanation(e,a){
 const vs=vars(e.model),w=e.state.n+e.state.m;
 if(e.phase==='decide')return `<div class="engine-stage"><h3>Decide: ¿continuar o terminar la tabla ${e.round}?</h3><p>Busca los valores de <b>Cj − Zj</b>. Si hay un número positivo, aún puede mejorar el resultado; si todos son ≤ 0, has alcanzado el criterio de optimalidad de este modelo. Decide tú:</p><div class="stop-buttons"><button class="btn primary" data-act="continue">Continuar</button><button class="btn secondary" data-act="finish">Terminar</button></div></div>`;
 if(e.phase==='enter')return `<div class="engine-stage"><h3>1. Escoge la columna pivote (azul)</h3><p>La columna pivote identifica la <b>variable que entra</b> a la solución básica. En este simplex de maximización se escoge el <b>mayor Cj − Zj positivo</b>. Si seleccionas correctamente, toda la columna quedará azul.</p><div class="engine-options">${vs.map((v,j)=>`<button class="engine-choice" data-act="enter" data-index="${j}">${v} · Cj−Zj = ${fmt(a.reduced[j])}</button>`).join('')}</div></div>`;
 if(e.phase==='leave')return `<div class="engine-stage"><h3>2. Encuentra la fila pivote (verde)</h3><p>La columna azul es <b>${vs[e.enter]}</b>, la variable entrante. Para escoger la fila pivote divide cada valor de <b>Solución (b)</b> entre el valor <b>a</b> de la columna azul, <b>solo cuando a &gt; 0</b>. Compara las razones válidas y escoge la <b>menor razón no negativa</b>. La variable que estaba en esa fila saldrá para que entre ${vs[e.enter]}.</p><div class="table-scroll"><table><thead><tr><th>Variable que puede salir</th><th>b</th><th>a</th><th>b/a (calcula)</th><th>Elige</th></tr></thead><tbody>${e.state.T.map((r,i)=>`<tr><td>${vs[e.state.base[i]]}</td><td>${fmt(r[w])}</td><td>${fmt(r[e.enter])}</td><td>${r[e.enter]>EPS?`<input class="input-cell" type="text" data-ratio="${i}" value="${esc(e.ratios[i]||'')}" placeholder="?" inputmode="decimal">`:'No se calcula (a ≤ 0)'}</td><td><button class="btn secondary small" data-act="leave" data-index="${i}" ${r[e.enter]>EPS?'':'disabled'}>Fila ${i+1}</button></td></tr>`).join('')}</tbody></table></div><p class="info-note">Una vez correcta, la fila se marcará en <b>verde</b> y la intersección con la columna azul será el <b>pivote naranja</b>.</p></div>`;
 if(e.phase==='norm'){const p=e.state.T[e.leave][e.enter];return `<div class="engine-stage"><h3>3. Prepara la fila pivote</h3><p>Listo: <b>entra ${vs[e.enter]} y sale ${vs[e.state.base[e.leave]]}</b>. En la nueva tabla, ${vs[e.enter]} ocupará la posición de ${vs[e.state.base[e.leave]]}.</p><p><b>Paso 1:</b> dividir toda la fila pivote <b>F${e.leave+1}</b> entre el elemento pivote <b>${fmt(p)}</b> para convertirlo en 1. Antes de calcular, demuestra que sabes elegir la operación y el <b>inverso multiplicativo</b> del pivote (el número que multiplicado por el pivote da 1).</p><div class="strategy-row"><div class="field"><label>¿Qué operación corresponde?</label><select id="engineOperation"><option value="">Elige una…</option><option value="divide">Dividir toda la fila entre el pivote</option><option value="add">Sumar el pivote a toda la fila</option><option value="multiply">Multiplicar la fila por el pivote</option></select></div><div class="field"><label>¿Cuál es el inverso del elemento pivote ${fmt(p)}?</label><input id="engineFactor" type="text" inputmode="decimal" placeholder="Escribe una fracción si corresponde"></div></div><button class="btn primary" data-act="chooseNorm">Comprobar operación e inverso</button></div>`;}
 if(e.phase==='normValues')return `<div class="engine-stage"><h3>4. Construye la fila pivote normalizada</h3><p>Ahora escribe cada resultado de <b>F${e.leave+1} nueva = F${e.leave+1} anterior ÷ (${fmt(e.state.T[e.leave][e.enter])})</b>. La tabla superior se actualizará en cuanto compruebes esta fila.</p>${rowBoxes(e,'norm')}<div class="button-row"><button class="btn primary" data-act="checkNorm">Comprobar y colocar fila en la tabla</button><button class="btn secondary" data-act="hint">Pista</button>${!e.grading&&e.attempts>=2?'<button class="btn ghost" data-act="revealNorm">Ver solución de esta fila (solo práctica)</button>':''}</div></div>`;
 if(e.phase==='elim'){const i=e.queue[e.queueIndex],coef=e.state.T[i][e.enter];return `<div class="engine-stage"><h3>5. Elige la operación para formar un cero en F${i+1}</h3><p>En la columna azul aparece <b>${fmt(coef)}</b> en la fila F${i+1}. Para convertirlo en 0, busca su <b>opuesto aditivo</b>: un número que al sumarse con ${fmt(coef)} dé cero. Luego <b>multiplica ese opuesto por toda la fila pivote ya normalizada y súmalo a F${i+1} anterior</b>.</p><div class="strategy-row"><div class="field"><label>¿Cuál operación necesitas?</label><select id="engineOperation"><option value="">Elige una…</option><option value="opposite">Fila anterior + (opuesto × fila pivote normalizada)</option><option value="add">Fila anterior + fila pivote sin multiplicar</option><option value="divide">Dividir la fila anterior entre el coeficiente</option></select></div><div class="field"><label>¿Cuál es el opuesto aditivo de ${fmt(coef)}?</label><input id="engineFactor" type="text" inputmode="decimal" placeholder="Escríbelo tú"></div></div><button class="btn primary" data-act="chooseElim">Comprobar operación y opuesto</button><p class="info-note">Ejemplo: si el coeficiente fuera 3, su opuesto sería −3 y haríamos F anterior + (−3 × fila pivote nueva).</p></div>`;}
 if(e.phase==='elimValues'){const i=e.queue[e.queueIndex],coef=e.state.T[i][e.enter];return `<div class="engine-stage"><h3>6. Calcula F${i+1} y observa cómo se llena la tabla</h3><p><b>F${i+1} nueva = F${i+1} anterior + (${fmt(-coef)}) × F${e.leave+1} normalizada</b>. Usa el opuesto que acabas de comprobar y completa todos los valores de la fila. Después de comprobar, se mostrará arriba; las otras filas no se borrarán.</p>${rowBoxes(e,'elim')}<div class="button-row"><button class="btn primary" data-act="checkElim">Comprobar y colocar fila en la tabla</button><button class="btn secondary" data-act="hint">Pista</button>${!e.grading&&e.attempts>=2?'<button class="btn ghost" data-act="revealElim">Ver solución de esta fila (solo práctica)</button>':''}</div></div>`;}
 if(e.phase==='z')return `<div class="engine-stage"><h3>7. Calcula primero la fila Zj</h3><p>La nueva tabla ya está construida. Multiplica el <b>Cb</b> de cada fila por el elemento de la columna correspondiente y suma. También debes calcular <b>Z</b> en la columna b. Tras comprobar, Zj aparecerá en la tabla superior.</p><div class="row-math-inputs">${['b',...vs].map((v,k)=>`<label class="math-input-label">Zj · ${v}<input type="text" data-cost-key="z${k===0?w:k-1}" class="${(e.invalidCost||[]).includes('z'+(k===0?w:k-1))?'invalid':''}" value="${esc(e.costDraft['z'+(k===0?w:k-1)]||'')}" placeholder="?"></label>`).join('')}</div><button class="btn primary" data-act="checkZ">Comprobar Zj y mostrarlo en la tabla</button></div>`;
 if(e.phase==='reduced')return `<div class="engine-stage"><h3>8. Ahora calcula Cj − Zj</h3><p>La fila Zj ya está a la vista. Para cada columna, resta su valor a <b>Cj</b>. Una vez comprobados los costos reducidos, podrás decidir si hay que continuar o terminar.</p><div class="row-math-inputs">${vs.map((v,j)=>`<label class="math-input-label">Cj−Zj · ${v}<input type="text" data-cost-key="r${j}" class="${(e.invalidCost||[]).includes('r'+j)?'invalid':''}" value="${esc(e.costDraft['r'+j]||'')}" placeholder="?"></label>`).join('')}</div><button class="btn primary" data-act="checkReduced">Comprobar Cj−Zj y mostrarlo</button></div>`;
 if(e.phase==='review')return `<div class="engine-stage"><h3>Tabla ${e.round} completa</h3><p>Has calculado la base, Zj y Cj−Zj. Ahora debes decidir, tú mismo, si corresponde continuar o terminar.</p><button class="btn primary" data-act="next">Revisar condición de parada →</button>${e.undo.length?'<button class="btn ghost" data-act="undo">Deshacer el último pivote</button>':''}</div>`;
 return '';
}

function renderEngine(e){
 const history=e.operations.map((n,i)=>`<li>${esc(n)}</li>`).join('');
 el(e.mount).innerHTML=`<div class="status-line">${e.grading?'Evaluación individual · sin respuestas automáticas':'Práctica guiada'} · Tabla ${e.round} · ${e.done?'Finalizada':'En desarrollo'}</div>${engineSnapshotTable(e)}${e.done?`<div class="report-ready"><h3>✓ Decidiste terminar y el criterio de optimalidad fue comprobado</h3>${interpreted(e.model,e.state)}</div>`:phaseExplanation(e,analyzeTableau(e.state))}${e.note?`<div class="feedback" role="status"><div class="${e.noteType}">${e.note}</div></div>`:''}<div class="live-history"><h3>Historial visible: decisiones y operaciones (${e.operations.length})</h3>${history?`<ol>${history}</ol>`:'<p>Aún no has realizado una operación. El historial se completará a medida que trabajes.</p>'}</div>`;
 el(e.mount).querySelectorAll('[data-act]').forEach(btn=>btn.addEventListener('click',()=>engineAct(e,btn.dataset.act,Number(btn.dataset.index))));
}
function readRow(e){const nodes=el(e.mount).querySelectorAll('[data-row-val]'),arr=[];let invalid=[];
 nodes.forEach(n=>{const j=Number(n.dataset.rowVal);e.draft[j]=n.value;try{arr[j]=parseMath(n.value)}catch{invalid.push(j);}});
 if(invalid.length){e.attempts++;e.invalidCols=invalid;const row=e.phase==='normValues'?e.leave:e.queue[e.queueIndex];e.note='Fila '+(row+1)+': completa o corrige '+invalid.map(j=>'columna '+(j===e.state.n+e.state.m?'b':vars(e.model)[j])).join(', ')+'.';e.noteType='hint';return null;}
 return arr;
}
function verifyRow(e,wanted){const supplied=readRow(e);if(!supplied)return null;const bad=[];
 supplied.forEach((v,j)=>{if(!near(v,wanted[j],1e-5))bad.push(j);});
 if(bad.length){e.attempts++;e.invalidCols=bad;const row=e.phase==='normValues'?e.leave:e.queue[e.queueIndex];e.note='Error en fila '+(row+1)+': '+bad.map(j=>'columna '+(j===wanted.length-1?'b':vars(e.model)[j])).join(', ')+'. Revisa la operación para cada celda resaltada.';e.noteType='hint';return null;}
 e.invalidCols=[];return supplied;
}
function verifyCostPhase(e,phase,a){const ns=el(e.mount).querySelectorAll('[data-cost-key]'),wrong=[],w=e.state.n+e.state.m;
 ns.forEach(node=>{const key=node.dataset.costKey;e.costDraft[key]=node.value;const j=Number(key.slice(1)),expected=phase==='z'?(j===w?a.z:a.zj[j]):a.reduced[j];let valid=false;
 try{valid=near(parseMath(node.value),expected,1e-5);}catch{}node.classList.toggle('invalid',!valid);
 if(!valid)wrong.push((phase==='z'?'Zj':'Cj−Zj')+', columna '+(j===w?'b':vars(e.model)[j]));});
 e.invalidCost=wrong.map(x=>{const match=x.match(/(?:Zj|Cj−Zj), columna (.*)$/);const j=match?match[1]:'';const col=j==='b'?w:vars(e.model).indexOf(j);return (phase==='z'?'z':'r')+col;});if(wrong.length){e.note='Corrige: '+wrong.join('; ')+'.';e.noteType='hint';return false;}e.invalidCost=[];return true;
}
function engineAct(e,act,index){const a=analyzeTableau(e.state),w=e.state.n+e.state.m,names=vars(e.model);const message=(text,type='info')=>{e.note=text;e.noteType=type;};
 try{
 if(act==='continue'){
  if(a.optimal)message('No corresponde continuar: todos los Cj−Zj ≤ 0. Selecciona Terminar.','hint');
  else if(a.unbounded)message('No existe razón mínima válida; el modelo es no acotado.','bad');
  else{e.phase='enter';e.operations.push(`Tabla ${e.round}: el estudiante elige CONTINUAR porque existe Cj−Zj positivo.`);message('Correcto. Ahora escoge la columna pivote.','ok');}
 }else if(act==='finish'){
  if(!a.optimal)message('Todavía hay Cj−Zj positivos. Corrige tu decisión: selecciona Continuar.','hint');
  else{e.done=true;e.phase='done';e.operations.push(`Tabla ${e.round}: el estudiante elige TERMINAR porque todos los Cj−Zj son ≤ 0.`);message('Has alcanzado el óptimo.','ok');if(e.grading){app.assess.finished=true;showStep('evalStage5',true);populateAssessmentAnswer();}else app.guideDone=true;}
 }else if(act==='enter'){
  if(index!==a.enter)message('Esa no es la columna con el mayor Cj−Zj positivo. Revisa la fila inferior.','hint');
  else{e.enter=index;e.phase='leave';e.operations.push(`Tabla ${e.round}: columna pivote ${names[index]} (azul), valor Cj−Zj = ${fmt(a.reduced[index])}.`);message('Columna azul: '+names[index]+' será la variable entrante.','ok');}
 }else if(act==='leave'){
  const ratioNodes=el(e.mount).querySelectorAll('[data-ratio]'),wrong=[];
  ratioNodes.forEach(n=>{const i=Number(n.dataset.ratio);e.ratios[i]=n.value;let valid=false;try{valid=near(parseMath(n.value),e.state.T[i][w]/e.state.T[i][e.enter],1e-5);}catch{}if(!valid)wrong.push(i+1);});
  if(wrong.length)message('Revisa las razones b/a de las filas '+wrong.join(', ')+'. Solo divide si a > 0.','hint');
  else if(index!==a.leave)message('Compara las razones calculadas: corresponde elegir la menor no negativa.','hint');
  else{e.leave=index;e.phase='norm';e.attempts=0;e.approvedRows=[];
   e.operations.push(`Tabla ${e.round}: fila pivote F${index+1} (verde); sale ${names[e.state.base[index]]}, entra ${names[e.enter]}; razón mínima ${fmt(a.ratios[index])}; elemento pivote ${fmt(e.state.T[index][e.enter])} (naranja).`);
   message('La fila '+(index+1)+' se marca en verde; el pivote, en naranja.','ok');}
 }else if(act==='chooseNorm'||act==='chooseElim'){
  const sel=el('engineOperation'),input=el('engineFactor');let supplied=null;try{supplied=parseMath(input.value);}catch{};
  if(act==='chooseNorm'){
   const p=e.state.T[e.leave][e.enter];if(sel.value!=='divide'||supplied===null||!near(supplied,1/p,1e-6))message('Revisa la operación o el inverso multiplicativo. Debe cumplir pivote × inverso = 1.','hint');
   else{e.phase='normValues';e.operations.push(`Tabla ${e.round}: eligió dividir toda F${e.leave+1} por ${fmt(p)} y escribió inverso multiplicativo ${fmt(supplied)}.`);message('Operación e inverso correctos. Calcula la nueva fila.','ok');}
  }else{
   const i=e.queue[e.queueIndex],coef=e.state.T[i][e.enter];if(sel.value!=='opposite'||supplied===null||!near(supplied,-coef,1e-6))message('Revisa la operación o el opuesto aditivo: coeficiente + opuesto debe dar 0.','hint');
   else{e.phase='elimValues';e.operations.push(`Tabla ${e.round}: eligió sumar el opuesto ${fmt(supplied)} × F${e.leave+1} normalizada a F${i+1}.`);message('Operación y opuesto correctos. Escribe la nueva fila.','ok');}
  }
 }else if(act==='checkNorm'||act==='revealNorm'){
  const p=e.state.T[e.leave][e.enter],expected=e.state.T[e.leave].map(v=>clean(v/p));
  let row=act==='revealNorm'?expected:verifyRow(e,expected);if(e.grading&&act==='revealNorm')row=null;
  if(row){e.norm=row;e.working=e.state.T.map(r=>[...r]);e.working[e.leave]=[...row];e.approvedRows=[e.leave];
   e.operations.push(`Tabla ${e.round}: F${e.leave+1} nueva = F${e.leave+1} anterior ÷ ${fmt(p)}. Resultado en orden [b, ${names.join(', ')}]: [${[row[w],...row.slice(0,w)].map(fmt).join(', ')}]${act==='revealNorm'?' (ayuda en práctica)':''}.`);
   if(act==='revealNorm')e.assisted++;e.queue=Array.from({length:e.state.m},(_,i)=>i).filter(i=>i!==e.leave);e.queueIndex=0;e.draft={};e.attempts=0;e.phase='elim';message('Correcto. Tu fila pivote normalizada ya aparece en la tabla superior.','ok');}
 }else if(act==='checkElim'||act==='revealElim'){
  const i=e.queue[e.queueIndex],factor=e.state.T[i][e.enter],expected=e.state.T[i].map((v,j)=>clean(v-factor*e.norm[j]));
  let row=act==='revealElim'?expected:verifyRow(e,expected);if(e.grading&&act==='revealElim')row=null;
  if(row){e.working[i]=row;e.approvedRows.push(i);
   e.operations.push(`Tabla ${e.round}: F${i+1} nueva = F${i+1} anterior + (${fmt(-factor)}) × F${e.leave+1} normalizada. Resultado [b, ${names.join(', ')}]: [${[row[w],...row.slice(0,w)].map(fmt).join(', ')}]${act==='revealElim'?' (ayuda en práctica)':''}.`);
   if(act==='revealElim')e.assisted++;e.queueIndex++;e.attempts=0;e.draft={};
   if(e.queueIndex>=e.queue.length){const next=pivotTableau(e.state,e.enter,e.leave);
    for(let ri=0;ri<e.state.m;ri++)for(let col=0;col<=w;col++)if(!near(e.working[ri][col],next.T[ri][col],1e-6))throw Error('Las operaciones no coinciden con la tabla calculada.');
    e.undo.push({state:clone(e.state),round:e.round,ops:e.operations.length});e.state={...next,T:e.working.map(r=>r.map(clean))};e.round++;e.tableHistory.push({state:clone(e.state),round:e.round});e.phase='z';e.costDraft={};e.zChecked=false;e.working=null;e.approvedRows=[];e.enter=-1;e.leave=-1;
    message('Tabla '+e.round+' lista, con todos los números verificados. Ahora calcula Zj.','ok');
   }else{e.phase='elim';message('Fila '+(i+1)+' calculada y mostrada en la tabla. Continúa con la siguiente fila.','ok');}
  }
 }else if(act==='checkZ'){
  if(verifyCostPhase(e,'z',a)){e.zChecked=true;e.phase='reduced';e.operations.push(`Tabla ${e.round}: el estudiante calculó Zj; [b, ${names.join(', ')}] = [${[a.z,...a.zj.slice(0,w)].map(fmt).join(', ')}].`);message('Zj comprobado: ya aparece en la tabla. Continúa con Cj−Zj.','ok');}
 }else if(act==='checkReduced'){
  if(verifyCostPhase(e,'reduced',a)){e.phase='review';e.operations.push(`Tabla ${e.round}: el estudiante calculó Cj−Zj = [${a.reduced.map(fmt).join(', ')}].`);message('Cj−Zj comprobado. Revisa si debes continuar o terminar.','ok');}
 }else if(act==='next'){e.phase='decide';message('Observa Cj−Zj y toma tu decisión.','info');}
 else if(act==='undo'&&e.undo.length){const prev=e.undo.pop();e.state=prev.state;e.round=prev.round;e.tableHistory.pop();e.operations.splice(prev.ops-1);e.enter=-1;e.leave=-1;e.zChecked=false;e.working=null;e.phase='decide';message('Se recuperó la tabla anterior. Puedes repetir el pivote.','info');}
 else if(act==='hint'){e.attempts++;message(e.phase==='normValues'?'Divide cada entrada entre el elemento pivote, incluido b.':e.phase==='elimValues'?'Multiplica el opuesto del coeficiente por cada elemento de la fila pivote y súmalo al número anterior de esa misma columna.':'Revisa el paso actual.','hint');}
 }catch(err){message(esc(err.message),'bad');}
 renderEngine(e);
}

function initGuided(){app.guide=engineNew(CASES.farm,'guidedEngine',false);renderEngine(app.guide);bind('calcRun','click',()=>{try{const t=parseMath(el('calcExpr').value,true);feedback('calcOutput','ok',`Resultado: <b>${fmt(t.value)}</b>${t.steps.length?'<br>'+t.steps.map(esc).join(' → '):''}`)}catch(e){feedback('calcOutput','bad',esc(e.message))}})}
/* Ejercicio de evaluación: tres variables y tres recursos; modelo, holguras, tabla, iteraciones y redacción. */
function renderAssessmentModel(){const m=CASES.assessment;let h='<div class="table-scroll"><table class="math-table"><thead><tr><th>Fila</th><th>X₁</th><th>X₂</th><th>X₃</th><th>Signo</th><th>b</th></tr></thead><tbody><tr><th>Max Z (miles de COP)</th>';for(let j=0;j<3;j++)h+=`<td><input class="input-cell" id="eval_c${j}" type="text" placeholder="?" aria-label="Beneficio X${j+1}"></td>`;h+='<td>Max.</td><td>—</td></tr>';for(let i=0;i<3;i++){h+=`<tr><th>${esc(m.resources[i])}</th>`;for(let j=0;j<3;j++)h+=`<td><input class="input-cell" id="eval_a${i}${j}" type="text" placeholder="?" aria-label="Consumo recurso ${i+1}, producto ${j+1}"></td>`;h+=`<td><select id="eval_sign${i}" aria-label="Signo restricción ${i+1}"><option value="">…</option><option value="le">≤</option><option value="ge">≥</option><option value="eq">=</option></select></td><td><input class="input-cell" id="eval_b${i}" type="text" placeholder="?" aria-label="Disponible recurso ${i+1}"></td></tr>`;}h+='</tbody></table></div><div class="field"><label for="eval_nonneg">Condición de no negatividad</label><select id="eval_nonneg"><option value="">Escoge…</option><option value="yes">X₁, X₂, X₃ ≥ 0</option><option value="no">Variables negativas</option></select></div>';el('assessmentModel').innerHTML=h;}
function initAssessment(){renderAssessmentModel();el('assessmentConversion').innerHTML='<div class="equations-editor">'+['Corte','Montaje','Acabado'].map((r,i)=>`<div class="field"><label for="eval_h${i}">${esc(r)} · escribe la ecuación completa</label><input type="text" id="eval_h${i}" placeholder="...X1 + ...X2 + ...X3 + S${i+1} = ..." spellcheck="false" autocomplete="off"><div class="feedback" id="eval_h_fb${i}"></div></div>`).join('')+'</div>';
 bind('checkAssessmentModel','click',()=>{const m=CASES.assessment;let errors=[];for(let j=0;j<3;j++)if(!checkNumber(`eval_c${j}`,m.c[j]))errors.push(`beneficio ${j+1}`);for(let i=0;i<3;i++){if(!checkNumber(`eval_b${i}`,m.b[i]))errors.push(`disponibilidad ${i+1}`);if(!choice(`eval_sign${i}`,'le'))errors.push(`signo ${i+1}`);for(let j=0;j<3;j++)if(!checkNumber(`eval_a${i}${j}`,m.A[i][j]))errors.push(`coeficiente ${i+1},${j+1}`);}if(!choice('eval_nonneg','yes'))errors.push('no negatividad');if(errors.length){feedback('assessmentModelFeedback','hint',`Revisa ${errors.length} elementos: ${errors.slice(0,5).join('; ')}. Utiliza los datos por lote de cada recurso. No se mostrará el resultado antes de corregir.`);return;}app.assess.modeled=true;app.assess.stage=Math.max(app.assess.stage,1);app.assess.enteredModel=copyModel(m);showStep('evalStage2',true);feedback('assessmentModelFeedback','ok','Modelo correcto. Tu siguiente paso es incorporar tres holguras y escribir las igualdades.');});
 bind('checkAssessmentConversion','click',()=>{const result=[0,1,2].map(i=>inspectEquation(`eval_h${i}`,CASES.assessment,i));result.forEach((errors,i)=>{el('eval_h_fb'+i).innerHTML=errors.length?'<div class="hint">Revisa fila '+(i+1)+': '+esc(errors.join(', '))+'</div>':'<div class="ok">Ecuación '+(i+1)+' comprobada.</div>';});if(result.some(errors=>errors.length)){feedback('assessmentConversionFeedback','hint','Hay errores en tus ecuaciones. Corrige los coeficientes o el lado derecho señalados en cada fila.');return;}app.assess.converted=true;app.assess.stage=Math.max(app.assess.stage,2);el('assessmentEqDisplay').innerHTML=titleModel(CASES.assessment,true);el('assessmentEqDisplay').hidden=false;makeInitial('assessmentInitial',CASES.assessment,'assess');showStep('evalStage3',true);feedback('assessmentConversionFeedback','ok','Las tres igualdades están correctas. Ahora completa Cj, Cb, b, cuerpo, Zj y Cj−Zj de la tabla inicial.');});
 bind('checkAssessmentInitial','click',()=>{if(!app.assess.converted)return;const outcome=verifyInitial('assessmentInitial','assess');if(outcome.wrong.length){feedback('assessmentInitialFeedback','hint',`Corrige estas casillas: ${esc(outcome.wrong.slice(0,12).join('; '))}${outcome.wrong.length>12?'…':''}.`);return;}app.assess.initial=true;app.assess.stage=Math.max(app.assess.stage,3);app.assess.enteredInitial=outcome.values;app.assess.engine=engineNew(CASES.assessment,'assessmentEngine',true);showStep('evalStage4',true);renderEngine(app.assess.engine);feedback('assessmentInitialFeedback','ok','Primera tabla comprobada. Inicia el procedimiento. Debes realizar las operaciones sin revelar automáticamente ninguna fila.');});
 bind('checkAssessmentAnswer','click',()=>{if(!app.assess.engine?.done){feedback('assessmentAnswerFeedback','hint','Termina primero todas las tablas y confirma la condición de parada.');return;}const s=extractSolution(CASES.assessment,app.assess.engine.state);const inputs=el('assessmentAnswer').querySelectorAll('[data-eval-x]');let errs=[];const given=[];for(let j=0;j<3;j++){try{const v=inputValue(inputs[j]);given.push(v);if(!near(v,s.x[j],1e-5))errs.push(`X${j+1}`)}catch{errs.push(`X${j+1}`)}}let z;try{z=number('evalZ');if(!near(z,s.objective,1e-5))errs.push('Z')}catch{errs.push('Z')}const interpretation=el('assessmentInterpretation').value.trim();if(errs.length){feedback('assessmentAnswerFeedback','hint',`Revisa ${errs.join(', ')}. Los valores no coinciden con tu última tabla o con la función objetivo.`);app.assess.approved=false;return;}if(interpretation.length<100){feedback('assessmentAnswerFeedback','hint','Los valores matemáticos son correctos, pero tu interpretación debe tener al menos 100 caracteres. Explica las tres producciones, el beneficio, las horas y tu recomendación.');app.assess.approved=false;return;}app.assess.answers={x:given,z,interpretation};app.assess.approved=true;app.assess.stage=5;feedback('assessmentAnswerFeedback','ok','Cálculos correctos e interpretación registrada. La aplicación comprueba las cantidades y el óptimo; la docente valorará tu argumentación empresarial. Ya puedes descargar la evidencia individual.');});
 showStep('evalStage2',false);showStep('evalStage3',false);showStep('evalStage4',false);showStep('evalStage5',false);}
function populateAssessmentAnswer(){const e=app.assess.engine;if(!e)return;el('assessmentAnswer').innerHTML=`<p>Escribe las cantidades y el margen total que obtuviste a partir de tu <b>última tabla</b>. La aplicación los comprobará con el modelo.</p><div class="choice-columns">${CASES.assessment.names.map((n,j)=>`<div class="field"><label for="evalX${j}">${esc(n)} · X${j+1}</label><input data-eval-x="${j}" id="evalX${j}" type="text" placeholder="Cantidad" inputmode="decimal"></div>`).join('')}<div class="field"><label for="evalZ">Margen total (miles de COP)</label><input id="evalZ" type="text" placeholder="Z" inputmode="decimal"></div></div><p class="info-note">Comprueba después cuántas horas utiliza cada recurso y qué holguras permanecen. Esa comparación debe aparecer en tu interpretación.</p>`;}
/* Segundo caso industrial: la solución se recalcula realmente usando el motor simplex. */
const SIM_FIELDS=[['c0','Margen lote ligero (US$)',120],['c1','Margen lote reforzado (US$)',90],['b0','Cartón disponible (kg)',200],['b1','Espuma disponible (kg)',128],['b2','Película protectora (kg)',220]];
function scenarioRead(){const m=copyModel(CASES.chocolate);m.c=[number('sim_c0'),number('sim_c1')];m.b=[number('sim_b0'),number('sim_b1'),number('sim_b2')];validateModel(m);return m;}
function simInfo(s,model){const r=s.solution;return `<div class="result-strip">${model.names.map((n,j)=>`<div class="result-stat"><span class="stat-label">${esc(n)}</span><strong>${fmt(r.x[j])}</strong></div>`).join('')}<div class="result-stat"><span class="stat-label">Margen máximo</span><strong>${money(r.objective,model.money)}</strong></div></div>`;}
function renderSimulation(){if(!app.simulation)return;const orig=solveSimplex(CASES.chocolate),current=app.simulation;if(current.status!=='optimal'){el('simulationResults').innerHTML='<div class="notice warning">El escenario no produjo un óptimo finito comprobado.</div>';return;}let h='<div class="two-cols"><div><h3>Datos originales</h3>'+simInfo(orig,orig.model)+'</div><div><h3>Escenario modificado</h3>'+simInfo(current,current.model)+'</div></div>';h+=`<div class="notice">Variación del margen: <b>${money(current.solution.objective-orig.solution.objective,'US$')}</b>. Este valor no descuenta inversiones o nuevos costos de compra que no estén incluidos en el modelo.</div>`;h+='<div class="table-scroll"><table><thead><tr><th>Recurso</th><th>Disponible inicial</th><th>Inicial: utilizado / holgura</th><th>Disponible nuevo</th><th>Nuevo: utilizado / holgura</th></tr></thead><tbody>';CASES.chocolate.resources.forEach((name,i)=>{h+=`<tr><td>${esc(name)}</td><td>${fmt(orig.model.b[i])}</td><td>${fmt(orig.solution.use[i])} / ${fmt(orig.solution.slack[i])}</td><td>${fmt(current.model.b[i])}</td><td>${fmt(current.solution.use[i])} / ${fmt(current.solution.slack[i])}</td></tr>`});h+='</tbody></table></div>';el('simulationResults').innerHTML=h;}
function initSimulation(){el('simulationEditor').innerHTML=SIM_FIELDS.map(([id,label,v])=>`<div class="field"><label for="sim_${id}">${esc(label)}</label><input type="text" id="sim_${id}" inputmode="decimal" value="${v}"></div>`).join('');bind('runSimulation','click',()=>{try{app.simulation=solveSimplex(scenarioRead());renderSimulation();el('simulationFeedback').innerHTML='';}catch(e){feedback('simulationFeedback','bad',esc(e.message))}});bind('resetSimulation','click',()=>{SIM_FIELDS.forEach(([id,_,v])=>el('sim_'+id).value=v);app.simulation=solveSimplex(CASES.chocolate);renderSimulation();});app.simulation=solveSimplex(CASES.chocolate);renderSimulation();}
/* Evidencia individual: solo tablas realmente completadas por el estudiante. */
function reportTableState(model,st,index){const a=analyzeTableau(st),names=vars(model),w=st.n+st.m;let h=`<h3>Tabla ${index} · Base: ${st.base.map(i=>names[i]).join(', ')}</h3><table><thead><tr><th colspan="3">Cj</th>${st.cj.map(v=>`<th>${fmt(v)}</th>`).join('')}</tr><tr><th>Cb</th><th>Base</th><th>b</th>${names.map(v=>`<th>${esc(v)}</th>`).join('')}</tr></thead><tbody>`;for(let i=0;i<st.m;i++)h+=`<tr><td>${fmt(st.cj[st.base[i]])}</td><td>${names[st.base[i]]}</td><td>${fmt(st.T[i][w])}</td>${st.T[i].slice(0,w).map(v=>`<td>${fmt(v)}</td>`).join('')}</tr>`;h+=`<tr><td colspan="2">Zj</td><td>${fmt(a.z)}</td>${a.zj.slice(0,w).map(v=>`<td>${fmt(v)}</td>`).join('')}</tr><tr><td colspan="2">Cj − Zj</td><td>—</td>${a.reduced.map(v=>`<td>${fmt(v)}</td>`).join('')}</tr></tbody></table>`;return h;}
function rawModelFields(){const m=CASES.assessment;let h='<table><thead><tr><th>Fila</th><th>X₁</th><th>X₂</th><th>X₃</th><th>Signo</th><th>b</th></tr></thead><tbody>';const value=id=>esc(el(id)?.value||'Sin escribir');h+=`<tr><td>Z</td>${[0,1,2].map(j=>`<td>${value('eval_c'+j)}</td>`).join('')}<td>Max</td><td>—</td></tr>`;for(let i=0;i<3;i++)h+=`<tr><td>${esc(m.resources[i])}</td>${[0,1,2].map(j=>`<td>${value(`eval_a${i}${j}`)}</td>`).join('')}<td>${{le:'≤',ge:'≥',eq:'='}[el('eval_sign'+i).value]||'?'}</td><td>${value('eval_b'+i)}</td></tr>`;return h+'</tbody></table>';}
function reportContent(){const a=app.assess,e=a.engine,complete=Boolean(a.approved&&a.finished&&e?.done);let h=`<h1>Laboratorio 3 · Método simplex de maximización</h1><p><b>Evidencia individual para evaluación</b><br><b>Estudiante:</b> ${esc(app.student||'No registrado')}<br><b>Fecha de generación:</b> ${esc(new Date().toLocaleString('es-CO'))}<br><b>Asignatura:</b> Programación Lineal · Ingeniería Industrial<br><b>Ejercicio:</b> Metalmecánica del Caribe S.A.S. (tres variables)</p><p class="${complete?'report-ready':'report-pending'}"><b>Estado de la entrega:</b> ${complete?'PROCEDIMIENTO COMPLETADO Y VALORES COMPROBADOS':'BORRADOR NO FINALIZADO: faltan comprobaciones o interpretación'}. ${complete?'Interpretación registrada para valoración docente.':'Los espacios pendientes no se presentan como operaciones realizadas.'}</p>`;
 h+='<h2>1. Formulación del modelo</h2>'+rawModelFields()+`<p><b>Resultado del control de formulación:</b> ${a.modeled?'Comprobado':'Pendiente o sin validar'}. ${a.modeled?'X₁ = lotes de soportes, X₂ = lotes de bases, X₃ = lotes de acoples; todas las variables son no negativas.':''}</p>`;
 h+='<h2>2. Conversión de desigualdades en igualdades</h2>';if(a.converted){h+=`<p>Igualdades redactadas y comprobadas por el estudiante:</p><ol>${[0,1,2].map(i=>`<li>${esc(el('eval_h'+i).value)}</li>`).join('')}</ol><p class="formula-preview">${titleModel(CASES.assessment,true)}</p>`}else h+='<p>Sin verificar. Debes agregar una holgura por cada restricción ≤.</p>';
 h+='<h2>3. Tabla inicial y procedimiento por iteraciones</h2>';if(e?.tableHistory?.length){e.tableHistory.forEach((entry,j)=>{h+=reportTableState(CASES.assessment,entry.state,j);const actions=e.operations.filter(x=>x.startsWith('Tabla '+j+':'));if(actions.length)h+=`<p><b>Selecciones, operaciones y resultados introducidos por el estudiante:</b></p><ol>${actions.map(s=>`<li>${esc(s)}</li>`).join('')}</ol>`;});}else if(a.initial)h+='<p>La primera tabla fue comprobada, pero no hay historial tabular disponible.</p>';else h+='<p>Primera tabla y operaciones aún no comprobadas.</p>';
 h+='<h2>4. Solución y verificación de restricciones</h2>';if(e?.done){const st=e.state,s=extractSolution(CASES.assessment,st);h+=`<p>Condición de optimalidad verificada: todos los Cj − Zj ≤ 0. El estudiante seleccionó «Terminar» después de ${e.round} pivoteos.</p><table><thead><tr><th>Variable</th><th>Valor</th></tr></thead><tbody>${s.x.map((v,j)=>`<tr><td>${esc(CASES.assessment.names[j])} (X${j+1})</td><td>${fmt(v)} lotes</td></tr>`).join('')}<tr><td>Margen máximo Z</td><td>${money(s.objective,'mil COP')}</td></tr></tbody></table><table><thead><tr><th>Recurso</th><th>Disponible (h)</th><th>Utilizado (h)</th><th>Holgura (h)</th></tr></thead><tbody>${CASES.assessment.resources.map((name,i)=>`<tr><td>${esc(name)}</td><td>${fmt(CASES.assessment.b[i])}</td><td>${fmt(s.use[i])}</td><td>${fmt(s.slack[i])}</td></tr>`).join('')}</tbody></table>`;}else h+='<p>El estudiante no ha comprobado todavía la condición de parada.</p>';
 h+='<h2>5. Interpretación y recomendación redactadas</h2>';let studentText=el('assessmentInterpretation').value.trim();h+=`<p><b>Respuesta del estudiante:</b> ${studentText?esc(studentText).replace(/\n/g,'<br>'):'Pendiente de redactar'}</p><p><b>Validación de resultados:</b> ${a.approved?'Resultados numéricos comprobados e interpretación registrada':'Pendiente'}. La redacción se valora por la docente; una longitud mínima no equivale a calidad argumentativa.</p>`;
 if(el('simArgument').value.trim())h+=`<h2>6. Reflexión adicional (escenario de empaques)</h2><p>${esc(el('simArgument').value.trim()).replace(/\n/g,'<br>')}</p>`;
 h+='<p class="fineprint">Documento generado localmente. Modelo lineal continuo de maximización con restricciones ≤, lados derechos no negativos y variables no negativas. Los datos industriales son didácticos.</p>';return h;}
function reportDoc(){const style=`body{color:#26394c;font:13px/1.5 Arial,sans-serif;max-width:950px;margin:24px auto;padding:0 18px}h1{color:#183b4c;font-size:23px}h2{color:#136c71;border-bottom:1px solid #b6ced7;font-size:17px;margin-top:24px;padding-bottom:7px}h3{font-size:14px;margin-top:20px}table{border-collapse:collapse;margin:11px 0;font-size:11px;width:100%}td,th{border:1px solid #c4d4da;padding:6px;white-space:nowrap;text-align:center}th{background:#ebf3f4}.formula-preview{background:#f5f9fa;border:1px solid #d6e5e9;padding:12px}.report-ready,.report-pending{padding:14px;border-radius:8px;background:#f0f7f7}.report-pending{background:#fff2e8}@page{size:A4 landscape;margin:13mm}h2,h3{break-after:avoid}table{break-inside:avoid}`;return `<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Laboratorio 3 · ${esc(app.student)} · ${app.assess.approved?'Completo':'Borrador'}</title><style>${style}</style></head><body>${reportContent()}</body></html>`;}
function downloadFile(filename,text,mime){const blob=new Blob([text],{type:mime}),link=document.createElement('a'),href=URL.createObjectURL(blob);link.href=href;link.download=filename;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(href),5000)}
function csvReport(){const e=app.assess.engine;const rows=[['Laboratorio 3','Método simplex','Ejercicio evaluable: tres variables'],['Estudiante',app.student],['Estado',app.assess.approved?'COMPLETADO':'BORRADOR INCOMPLETO'],[]];if(!e?.tableHistory?.length)return '\ufeff'+rows.map(r=>r.join(';')).join('\r\n');const names=vars(CASES.assessment);e.tableHistory.forEach((row,j)=>{const st=row.state,a=analyzeTableau(st),w=st.n+st.m;rows.push(['TABLA '+j],['Cj','','',...st.cj.map(fmt)],['Cb','Base','b',...names]);for(let i=0;i<st.m;i++)rows.push([fmt(st.cj[st.base[i]]),names[st.base[i]],fmt(st.T[i][w]),...st.T[i].slice(0,w).map(fmt)]);rows.push(['','Zj',fmt(a.z),...a.zj.slice(0,w).map(fmt)],['','Cj-Zj','',...a.reduced.map(fmt)]);e.operations.filter(s=>s.startsWith('Tabla '+j+':')).forEach(s=>rows.push(['OPERACIÓN',s]));rows.push([])});rows.push(['INTERPRETACIÓN',el('assessmentInterpretation').value.trim()]);return '\ufeff'+rows.map(r=>r.map(x=>`"${String(x??'').replace(/"/g,'""')}"`).join(';')).join('\r\n');}
function renderSummary(){const s=app.assess;const rows=[['Nombre y apellido registrado',Boolean(app.student)],['Modelo de tres variables',s.modeled],['Holguras y ecuaciones',s.converted],['Primera tabla verificada',s.initial],['Todas las iteraciones completadas',s.finished],['Criterio de parada comprobado',Boolean(s.engine?.done)],['Valores e interpretación registrados',s.approved]];el('learningSummary').innerHTML=`<p><b>Estudiante:</b> ${esc(app.student)}</p><div class="table-scroll"><table><thead><tr><th>Evidencia evaluable</th><th>Estado</th></tr></thead><tbody>${rows.map(([n,b])=>`<tr><td>${esc(n)}</td><td>${b?'✓ Comprobado':'Pendiente'}</td></tr>`).join('')}</tbody></table></div><p class="${s.approved?'report-ready':'report-pending'}">${s.approved?'Tu procedimiento está listo para descargar. El informe incluye todas las tablas que hiciste y tu interpretación.':'Aún hay etapas pendientes. Puedes conservar un borrador, pero no se marcará como entrega completa.'}</p>`;}
function initReport(){bind('exportReport','click',()=>{if(!app.student){feedback('reportFeedback','bad','Debes guardar tu nombre y apellido.');return;}downloadFile(`Laboratorio3_Simplex_${safeName()}_${app.assess.approved?'Completo':'Borrador'}.html`,reportDoc(),'text/html;charset=utf-8');feedback('reportFeedback','ok','Archivo HTML individual generado con tu nombre y las tablas completadas en esta sesión.');});bind('exportData','click',()=>{if(!app.student){feedback('reportFeedback','bad','Es necesario registrar el nombre.');return;}downloadFile(`Tablas_Simplex_${safeName()}.csv`,csvReport(),'text/csv;charset=utf-8');feedback('reportFeedback','ok','Tablas CSV exportadas; también se indica si el procedimiento está incompleto.');});bind('printReport','click',()=>{if(!app.student){feedback('reportFeedback','bad','Es necesario registrar el nombre.');return;}el('printArea').innerHTML=reportContent();feedback('reportFeedback','info','Se abrirá el cuadro de impresión. Elige «Guardar como PDF» como destino y confirma para descargar tu archivo completo, con tablas e historial.');window.print()});}
function boot(){initNavigation();initIdentity();initFormulation();initQuiz();initTransformation();initInitial();initGuided();initAssessment();initSimulation();initReport();activateScene(0);}
if(typeof document!=='undefined')document.addEventListener('DOMContentLoaded',boot);
if(typeof module!=='undefined'&&module.exports)module.exports={CASES,parseMath,initializeTableau,analyzeTableau,pivotTableau,solveSimplex,extractSolution,fmt,verifyResult};
